
(function(){
  // ===========================================================================
  //  DECLARACIONES v3
  //  Flujo: tocar "Declaraciones" -> pantalla inicial (logo + tarjetas de tipos).
  //  Elegir un tipo -> selector de AÑO (independiente por tipo) + tabla del año.
  //  Modelo: tab.types = [ { id,name,icon,color, cols:[...], years:{ '2025':{id,rows:[]} } } ]
  // ===========================================================================
  const DECL = window.__DECL = window.__DECL || { search:{}, view:{}, filter:{}, nav:{} };
  if(!DECL.nav) DECL.nav = {};
  const LOGO = "data:image/png;base64,";

  function declTab(tabId){ return state.tabs.find(t => t.id === tabId && t.type === 'declaraciones'); }
  const _rk = ()=> (typeof genRowKey==='function'?genRowKey():'r_'+Date.now()+'_'+Math.random().toString(36).slice(2,7));
  const _ck = ()=> (typeof genColKey==='function'?genColKey():'c_'+Date.now()+'_'+Math.random().toString(36).slice(2,7));
  const _id = (p)=> p+'_'+Date.now()+'_'+Math.random().toString(36).slice(2,6);
  const TYPE_COLORS = ['#2f6f4f','#1e497c','#8a5a00','#7a3b8f','#0f6e72','#9a3b3b','#3d5a2a'];

  function colsIRPF(){ return [
      {key:_ck(),label:'Cliente',ctype:'text'},
      {key:_ck(),label:'Hecho IRPF',ctype:'checkbox'},
      {key:_ck(),label:'Hecho IVA',ctype:'tag',options:['SI','No','N/A']},
      {key:_ck(),label:'Presentado',ctype:'date'},
      {key:_ck(),label:'Importe',ctype:'money',currency:'$U'},
      {key:_ck(),label:'Medio de pago',ctype:'tag',options:['Scotia','BBVA','Itaú','Santander','BROU','Efectivo','Transferencia']},
      {key:_ck(),label:'Fecha de pago',ctype:'date'},
      {key:_ck(),label:'Ejecutor',ctype:'person'},
      {key:_ck(),label:'Timbre',ctype:'money',currency:'$U'},
      {key:_ck(),label:'Saldo / Notas',ctype:'text'},
      {key:_ck(),label:'Estado',ctype:'tag',options:['Pendiente','En curso','Presentada','Cobrada'],
        tagColors:{'Pendiente':'#fdecc8','En curso':'#dbe8fb','Presentada':'#d6f0df','Cobrada':'#d4eef1'}} ];
  }
  function colsGeneric(){ return [
      {key:_ck(),label:'Cliente',ctype:'text'},
      {key:_ck(),label:'Presentado',ctype:'date'},
      {key:_ck(),label:'Importe',ctype:'money',currency:'$U'},
      {key:_ck(),label:'Saldo / Notas',ctype:'text'},
      {key:_ck(),label:'Estado',ctype:'tag',options:['Pendiente','En curso','Presentada','Cobrada'],
        tagColors:{'Pendiente':'#fdecc8','En curso':'#dbe8fb','Presentada':'#d6f0df','Cobrada':'#d4eef1'}} ];
  }
  function makeType(name, icon, color, cols, year){
    const ty = { id:_id('dty'), name:name, icon:icon||'📄', color:color||'#2f6f4f', cols:cols||colsGeneric(), years:{} };
    if(year) ty.years[year] = { id:_id('dyr'), rows:[] };
    return ty;
  }

  window.declEnsureTypes = function(tab){
    if(!tab || tab.type!=='declaraciones') return [];
    if(Array.isArray(tab.types)) return tab.types;
    const types = [];
    const folders = Array.isArray(tab.folders) ? tab.folders : [];
    folders.forEach(f=>{
      const blk = f.block || {cols:[],rows:[]};
      const m = (f.name||'').match(/(19|20)\d{2}/);
      const year = (f.year && /^\d{4}$/.test(''+f.year)) ? (''+f.year) : (m ? m[0] : '2025');
      const baseName = (f.name||'Declaración').replace(/\s*(19|20)\d{2}\s*/,'').trim() || (f.name||'Declaración');
      let ty = types.find(t => t.name.toLowerCase() === baseName.toLowerCase());
      if(!ty){ ty = { id: f.id || _id('dty'), name: baseName, icon: f.icon||'📄', color: f.color||'#2f6f4f', cols:(blk.cols||[]), years:{} }; types.push(ty); }
      ty.years[year] = { id: blk.id || _id('dyr'), rows: (blk.rows||[]) };
    });
    if(!types.length) types.push(makeType('IRPF','📄','#2f6f4f', colsIRPF(), '2025'));
    tab.types = types; delete tab.folders;
    return tab.types;
  };

  // Semillas y arreglos de una sola vez (IRPF -> 2025; crear IVA y Fonasa vacías)
  function seed(tab){
    const ts = window.declEnsureTypes(tab);
    let changed=false;
    if(!tab._yfix){
      const irpf = ts.find(t=>/irpf/i.test(t.name));
      if(irpf){ const ys=Object.keys(irpf.years);
        if(ys.length===1 && ys[0]!=='2025' && !irpf.years['2025']){ irpf.years['2025']=irpf.years[ys[0]]; delete irpf.years[ys[0]]; changed=true; }
      }
      tab._yfix=true; changed=true;
    }
    if(!tab._seeded){
      [['IVA','#1e497c'],['Fonasa','#8a5a00']].forEach(([nm,col])=>{
        if(!ts.some(t=>t.name.toLowerCase()===nm.toLowerCase())){ ts.push(makeType(nm,'📄',col, colsGeneric(), '2025')); changed=true; }
      });
      tab._seeded=true; changed=true;
    }
    if(changed) saveState();
    return ts;
  }

  function types(tab){ return window.declEnsureTypes(tab); }
  function typeById(tab, id){ return types(tab).find(t=>t.id===id) || null; }
  function activeType(tab){ const ts=types(tab); if(!ts.length) return null; const id=userPrefs['declType_'+tab.id]; return ts.find(t=>t.id===id)||ts[0]; }
  function yearsOf(ty){ return Object.keys(ty.years||{}).sort(); }
  function yearOptions(ty){
    const ex = Object.keys(ty.years||{}).map(Number).filter(n=>!isNaN(n));
    const now = new Date().getFullYear();
    const lo = Math.min(2025, now, ex.length?Math.min(...ex):2025);
    const hi = Math.max(now+1, ex.length?Math.max(...ex):now+1);
    const out=[]; for(let y=lo;y<=hi;y++) out.push(String(y)); return out;
  }
  function activeYear(tab, ty){
    const ys = yearsOf(ty);
    if(!ys.length){ ty.years['2025']={id:_id('dyr'),rows:[]}; return '2025'; }
    const stored = userPrefs['declYear_'+tab.id+'_'+ty.id];
    if(stored && ty.years[stored]) return stored;
    return ys.includes('2025') ? '2025' : ys[0];
  }

  function fmtMoney(n, curr){ curr=curr||'$U'; return curr+' '+Number(n||0).toLocaleString('es-UY',{minimumFractionDigits:2,maximumFractionDigits:2}); }
  function cellText(col, row){ const v=row[col.key];
    switch(col.ctype){
      case 'checkbox': return v?'sí':'no';
      case 'money': return v!=null?fmtMoney(v,col.currency):'';
      case 'date': return v?new Date(v+'T12:00:00').toLocaleDateString('es-UY',{day:'2-digit',month:'2-digit',year:'numeric'}):'';
      case 'person': { if(!v) return ''; const u=(typeof findUserByName==='function')?findUserByName(v):null; return u?(u.displayName||u.name):v; }
      default: return v!=null?String(v):'';
    }
  }

  const STATE_PALETTE = {
    'pendiente':{bg:'#fdecc8',fg:'#8a5a00',bd:'#f0cf86'}, 'en curso':{bg:'#dbe8fb',fg:'#1e4e84',bd:'#a9c6ef'},
    'en proceso':{bg:'#dbe8fb',fg:'#1e4e84',bd:'#a9c6ef'}, 'presentada':{bg:'#d6f0df',fg:'#1d7a48',bd:'#9ad6b2'},
    'presentado':{bg:'#d6f0df',fg:'#1d7a48',bd:'#9ad6b2'}, 'cobrada':{bg:'#d4eef1',fg:'#10707c',bd:'#9fd6dd'},
    'cobrado':{bg:'#d4eef1',fg:'#10707c',bd:'#9fd6dd'}, 'si':{bg:'#d6f0df',fg:'#1d7a48',bd:'#9ad6b2'},
    'no':{bg:'#fbe0df',fg:'#a13530',bd:'#f0b3b0'}, 'n/a':{bg:'#eceef1',fg:'#6b7280',bd:'#d8dce2'}
  };
  window.declFgFor = function(bg){ try{ const c=bg.replace('#',''); const r=parseInt(c.substr(0,2),16),g=parseInt(c.substr(2,2),16),b=parseInt(c.substr(4,2),16);
      return ((0.299*r+0.587*g+0.114*b)/255)>0.62?'#1b1f24':'#ffffff'; }catch(e){ return '#1b1f24'; } };
  function tagStyle(col,val){ if(val==null||val==='') return null;
    const custom = col && col.tagColors && col.tagColors[val]; if(custom) return {bg:custom,fg:window.declFgFor(custom),bd:custom};
    const p = STATE_PALETTE[String(val).toLowerCase()]; if(p) return p; return {bg:'#eef0f3',fg:'#3a414b',bd:'#dfe3e8'}; }
  function findColByKey(tab, key){ for(const ty of types(tab)){ const c=(ty.cols||[]).find(c=>c.key===key); if(c) return c; } return null; }

  // ===== Celda con edición directa =====
  let _curTabId = null;
  function declCell(blkId, col, row){
    const v=row[col.key], k=col.key; const ref="'"+blkId+"','"+row.__key+"','"+k+"'";
    switch(col.ctype){
      case 'text':   return '<input class="decl-inp" type="text" value="'+bbEscape(v||'')+'" placeholder="—" onchange="declSet('+ref+',this.value)">';
      case 'number': return '<input class="decl-inp decl-num" type="number" step="any" placeholder="—" value="'+(v!=null?v:'')+'" onchange="declSet('+ref+',this.value===\'\'?null:parseFloat(this.value))">';
      case 'money': { const c=col.currency||'$U'; return '<span class="decl-money"><span class="decl-cur">'+bbEscape(c)+'</span><input class="decl-inp decl-num" type="number" step="any" placeholder="0" value="'+(v!=null?v:'')+'" onchange="declSet('+ref+',this.value===\'\'?null:parseFloat(this.value))"></span>'; }
      case 'date':   return '<input class="decl-inp decl-date" type="date" value="'+(v||'')+'" onchange="declSet('+ref+',this.value)">';
      case 'checkbox': return '<input type="checkbox" class="decl-chk" '+(v?'checked':'')+' onchange="declSet('+ref+',this.checked)">';
      case 'tag': { const opts=col.options||[]; const st=tagStyle(col,v); const sa=st?' style="background:'+st.bg+';color:'+st.fg+';border-color:'+st.bd+';"':'';
        return '<select class="decl-state"'+sa+' onchange="declOnTag(this,'+ref+')"><option value="">—</option>'+opts.map(o=>'<option value="'+bbEscape(o)+'"'+(v===o?' selected':'')+'>'+bbEscape(o)+'</option>').join('')+'</select>'; }
      case 'person': { const opts=(typeof getValidUsers==='function')?getValidUsers():[]; return '<select class="decl-inp" onchange="declSet('+ref+',this.value)"><option value="">—</option>'+opts.map(u=>'<option value="'+bbEscape(u.name)+'"'+(v===u.name?' selected':'')+'>'+bbEscape(u.displayName||u.name)+'</option>').join('')+'</select>'; }
      default: return (typeof renderCTableCell==='function') ? renderCTableCell(declTab(_curTabId), {id:blkId,cols:[],rows:[]}, col, row) : bbEscape(v||'');
    }
  }

  // ===== Mutaciones =====
  function locateBlock(blkId){ for(const tab of state.tabs){ if(tab.type!=='declaraciones') continue; for(const ty of types(tab)){ for(const y in ty.years){ if(ty.years[y].id===blkId) return {tab,ty,year:y,yb:ty.years[y]}; } } } return null; }
  window.declSet = function(blkId, rowKey, colKey, value){ const loc=locateBlock(blkId); if(!loc) return; const row=(loc.yb.rows||[]).find(r=>r.__key===rowKey); if(!row) return; row[colKey]=value; saveState(); };
  window.declOnTag = function(sel, blkId, rowKey, colKey){ window.declSet(blkId,rowKey,colKey,sel.value); const col=findColByKey(declTab(_curTabId),colKey); const st=col?tagStyle(col,sel.value):null;
    if(st){ sel.style.background=st.bg; sel.style.color=st.fg; sel.style.borderColor=st.bd; } else { sel.style.background=''; sel.style.color=''; sel.style.borderColor=''; }
    try{ window.declSyncIva(blkId,rowKey,colKey,sel.value); }catch(e){} };
  window.declAddRow = function(tabId){ const tab=declTab(tabId); if(!tab) return; const ty=activeType(tab); const y=activeYear(tab,ty); ty.years[y].rows=ty.years[y].rows||[]; ty.years[y].rows.push({__key:_rk()}); saveState(); renderContent(); };
  window.declRemoveRow = function(tabId, rowKey){ const tab=declTab(tabId); if(!tab) return; const ty=activeType(tab); const y=activeYear(tab,ty); ty.years[y].rows=(ty.years[y].rows||[]).filter(r=>r.__key!==rowKey); saveState(); renderContent(); };
  window.declRemoveCol = function(tabId, colKey){ const tab=declTab(tabId); if(!tab) return; const ty=activeType(tab); const col=(ty.cols||[]).find(c=>c.key===colKey);
    if(!confirm('¿Eliminar la columna “'+(col?col.label:'')+'”? Se borra en todos los años de '+ty.name+'.')) return;
    ty.cols=(ty.cols||[]).filter(c=>c.key!==colKey); Object.keys(ty.years).forEach(y=>{ (ty.years[y].rows||[]).forEach(r=>{ delete r[colKey]; }); }); saveState(); renderContent(); };

  // ===== Sincronización IRPF -> IVA + papelera =====
  function findIvaType(tab){ return types(tab).find(t=>t.name.trim().toLowerCase()==='iva') || null; }
  function ivaCols(ty){
    let cli=(ty.cols||[]).find(c=>c.ctype==='text');
    let fecha=(ty.cols||[]).find(c=>c.ctype==='date');
    let nota=(ty.cols||[]).find(c=>c.ctype==='text' && c!==cli);
    let estado=(ty.cols||[]).find(c=>c.ctype==='tag' && /estado/i.test(c.label));
    if(!cli){ cli={key:_ck(),label:'Cliente',ctype:'text'}; ty.cols.unshift(cli); }
    if(!fecha){ fecha={key:_ck(),label:'Fecha de presentación',ctype:'date'}; ty.cols.push(fecha); }
    if(!nota){ nota={key:_ck(),label:'Nota',ctype:'text'}; ty.cols.push(nota); }
    if(!estado){ estado={key:_ck(),label:'Estado',ctype:'tag',options:['Pendiente','En curso','Presentada','Cobrada'],tagColors:{'Pendiente':'#fdecc8','En curso':'#dbe8fb','Presentada':'#d6f0df','Cobrada':'#d4eef1'}}; ty.cols.push(estado); }
    return {cli,fecha,nota,estado};
  }
  window.declSyncIva = function(blkId, rowKey, colKey, value){
    const loc=locateBlock(blkId); if(!loc) return; const tab=loc.tab, srcTy=loc.ty, year=loc.year;
    if(!/irpf/i.test(srcTy.name)) return;
    const col=(srcTy.cols||[]).find(c=>c.key===colKey); if(!col || !/iva/i.test(col.label)) return;
    const iva=findIvaType(tab); if(!iva) return;
    const srcIdCol=(srcTy.cols||[]).find(c=>c.ctype==='text')||srcTy.cols[0];
    const srcRow=(loc.yb.rows||[]).find(r=>r.__key===rowKey); if(!srcRow) return;
    const name=srcRow[srcIdCol.key]||'';
    if(!iva.years[year]) iva.years[year]={id:_id('dyr'),rows:[]};
    const yb=iva.years[year]; const cols=ivaCols(iva); iva.trash=iva.trash||[];
    const isSi=/^s[ií]$/i.test(String(value).trim());
    if(isSi){
      if((yb.rows||[]).some(r=>r._src===rowKey && r._auto==='irpf')){ saveState(); return; }
      const ti=iva.trash.findIndex(t=>t.year===year && t.row && t.row._src===rowKey && t.row._auto==='irpf');
      if(ti>=0){ yb.rows.push(iva.trash[ti].row); iva.trash.splice(ti,1); saveState(); if(typeof toast==='function') toast('✓ '+(name||'Cliente')+' restablecido en IVA '+year); return; }
      const nr={__key:_rk(), _auto:'irpf', _src:rowKey}; nr[cols.cli.key]=name; nr[cols.estado.key]='Pendiente';
      yb.rows.push(nr); saveState(); if(typeof toast==='function') toast('✓ '+(name||'Cliente')+' agregado a IVA '+year);
    } else {
      const idx=(yb.rows||[]).findIndex(r=>r._src===rowKey && r._auto==='irpf');
      if(idx>=0){ const row=yb.rows[idx]; yb.rows.splice(idx,1); iva.trash.push({year:year, row:row, name:(row[cols.cli.key]||name), ts:Date.now()}); saveState(); if(typeof toast==='function') toast('🗑 '+(name||'Cliente')+' fue a la papelera de IVA'); }
    }
  };
  window.declOpenTrash = function(tabId, typeId){
    const tab=declTab(tabId); if(!tab) return; const ty=typeById(tab,typeId); if(!ty) return; ty.trash=ty.trash||[];
    _trashCtx={tabId,typeId};
    const body=document.getElementById('decl-trash-body');
    if(!ty.trash.length){ body.innerHTML='<div style="padding:18px;text-align:center;color:var(--c-text-muted,#8a93a0);font-size:13px;">La papelera está vacía.</div>'; }
    else body.innerHTML = ty.trash.map((t,i)=>'<div class="dca-row" style="justify-content:space-between;"><span><b style="font-weight:600;">'+bbEscape(t.name||'(sin nombre)')+'</b> <span style="color:var(--c-text-muted,#8a93a0);font-size:12px;">· año '+t.year+'</span></span><span style="display:flex;gap:6px;"><button class="dca-mini" onclick="declRestoreTrash(\''+tabId+'\',\''+typeId+'\','+i+')">↩ Restaurar</button><button class="dca-mini" style="color:#a83232;border-color:#f0b3b0;" onclick="declDeleteTrash(\''+tabId+'\',\''+typeId+'\','+i+')">Eliminar</button></span></div>').join('');
    document.getElementById('decl-trash-modal').classList.add('open');
  };
  window.declRestoreTrash = function(tabId, typeId, idx){
    const tab=declTab(tabId); if(!tab) return; const ty=typeById(tab,typeId); if(!ty||!ty.trash[idx]) return;
    const it=ty.trash[idx]; if(!ty.years[it.year]) ty.years[it.year]={id:_id('dyr'),rows:[]};
    ty.years[it.year].rows.push(it.row); ty.trash.splice(idx,1); saveState(); renderContent();
    if((ty.trash||[]).length) declOpenTrash(tabId,typeId); else closeModal('decl-trash-modal');
    toast('↩ Fila restaurada');
  };
  window.declDeleteTrash = function(tabId, typeId, idx){
    const tab=declTab(tabId); if(!tab) return; const ty=typeById(tab,typeId); if(!ty||!ty.trash[idx]) return;
    ty.trash.splice(idx,1); saveState();
    if((ty.trash||[]).length) declOpenTrash(tabId,typeId); else { closeModal('decl-trash-modal'); renderContent(); }
  };
  let _trashCtx=null;

  // ===== Navegación tipos / pantalla inicial =====
  window.declTabClick = function(tabId){ DECL.nav[tabId]=null; if(userPrefs.activeTabId!==tabId){ switchTab(tabId); } else { renderContent(); } };
  window.declBackLanding = function(tabId){ DECL.nav[tabId]=null; renderContent(); };
  window.declOpenType = function(tabId, typeId){ DECL.nav[tabId]=typeId; userPrefs['declType_'+tabId]=typeId; saveUserPrefs(); if(userPrefs.activeTabId!==tabId){ switchTab(tabId); } else { renderContent(); } };
  window.declGoType = window.declOpenType;
  window.declAddType = function(tabId){ const tab=declTab(tabId); if(!tab) return;
    const name=prompt('Nombre del tipo de declaración (ej: IRAE, Cierres, IVA…):',''); if(name===null) return; const nm=name.trim(); if(!nm){ toast('Poné un nombre'); return; }
    const ts=types(tab); const color=TYPE_COLORS[ts.length % TYPE_COLORS.length]; const isIrpf=/irpf/i.test(nm);
    const ty=makeType(nm,'📄',color, isIrpf?colsIRPF():colsGeneric(), '2025'); ts.push(ty);
    DECL.nav[tab.id]=ty.id; userPrefs['declType_'+tab.id]=ty.id; saveUserPrefs(); saveState();
    if(userPrefs.activeTabId!==tab.id) switchTab(tab.id); else renderContent(); toast('✓ Tipo “'+nm+'” creado'); };
  window.declRenameType = function(tabId, typeId){ const tab=declTab(tabId); if(!tab) return; const ty=typeById(tab,typeId); if(!ty) return;
    const name=prompt('Nuevo nombre del tipo:', ty.name); if(name===null) return; if(name.trim()){ ty.name=name.trim(); saveState(); renderContent(); } };
  window.declDeleteType = function(tabId, typeId){ const tab=declTab(tabId); if(!tab) return; const ts=types(tab); const ty=ts.find(t=>t.id===typeId); if(!ty) return;
    if(ts.length<=1){ toast('Tiene que quedar al menos un tipo'); return; }
    if(!confirm('¿Eliminar el tipo “'+ty.name+'” con todos sus años y datos?')) return;
    tab.types=ts.filter(t=>t.id!==typeId); DECL.nav[tab.id]=null; saveState(); renderContent(); };

  // ===== Años =====
  window.declSetYear = function(tabId, typeId, year){ const tab=declTab(tabId); const ty=typeById(tab,typeId); if(ty && !ty.years[year]){ ty.years[year]={id:_id('dyr'),rows:[]}; saveState(); } userPrefs['declYear_'+tabId+'_'+typeId]=year; saveUserPrefs(); renderContent(); };
  window.declStepYear = function(tabId, typeId, dir){ const tab=declTab(tabId); const ty=typeById(tab,typeId); if(!ty) return; const ys=yearOptions(ty); const cur=activeYear(tab,ty); let i=ys.indexOf(cur)+dir; if(i<0||i>=ys.length) return; window.declSetYear(tabId,typeId,ys[i]); };
  window.declAddYear = function(tabId){ const tab=declTab(tabId); if(!tab) return; const ty=activeType(tab); const def=String(new Date().getFullYear());
    const y=prompt('¿Qué año querés agregar a “'+ty.name+'”?', def); if(y===null) return; const yr=String(y).trim(); if(!/^\d{4}$/.test(yr)){ toast('Poné un año de 4 dígitos'); return; }
    if(!ty.years[yr]) ty.years[yr]={id:_id('dyr'),rows:[]}; userPrefs['declYear_'+tab.id+'_'+ty.id]=yr; saveUserPrefs(); saveState(); renderContent(); toast('📅 Año '+yr+' listo en '+ty.name); };

  // ===== Filtrado =====
  function fkey(ty,year){ return ty.id+'_'+year; }
  function visibleRows(ty, year){ let rows=(ty.years[year].rows||[]).slice(); const k=fkey(ty,year); const q=(DECL.search[k]||'').toLowerCase(); const f=DECL.filter[k]||'';
    const estadoCol=(ty.cols||[]).find(c=>c.ctype==='tag' && /estado/i.test(c.label));
    if(q) rows=rows.filter(r=>(ty.cols||[]).some(c=>cellText(c,r).toLowerCase().includes(q)));
    if(f && estadoCol) rows=rows.filter(r=>r[estadoCol.key]===f); return rows; }

  function wm(op){ return '<div aria-hidden="true" style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none;z-index:0;"><img src="'+LOGO+'" style="width:340px;max-width:55%;opacity:'+op+';filter:grayscale(.1);"></div>'; }

  // ===== Render principal =====
  window.renderDeclaraciones = function(tab){
    _curTabId = tab.id;
    seed(tab);
    const navId = DECL.nav[tab.id];
    const ty = navId ? typeById(tab, navId) : null;
    let h = '<div class="decl-wrap" style="position:relative;">';
    if(!ty){ h += renderLanding(tab); h += '</div>'; return h; }
    h += renderTypeView(tab, ty); h += '</div>'; return h;
  };

  function renderLanding(tab){
    const ts = types(tab);
    const card = (t)=> '<div class="decl-tcard" onclick="declOpenType(\''+tab.id+'\',\''+t.id+'\')"><span class="tdot" style="background:'+(t.color||'#2f6f4f')+'"></span><span class="tname">'+bbEscape(t.name)+'</span></div>';
    let h = wm(0.10);
    h += '<div class="decl-landing">';
    h += '<div class="decl-land-title">Declaraciones</div>';
    h += '<div class="decl-land-sub">¿En qué declaración vamos a trabajar hoy?</div>';
    h += '<div class="decl-tcards">'+ ts.map(card).join('') + '<div class="decl-tcard add" onclick="declAddType(\''+tab.id+'\')"><i class="ti ti-plus"></i> Tipo</div></div>';
    h += '</div>';
    return h;
  }

  function renderTypeView(tab, ty){
    const year = activeYear(tab, ty);
    const yopts = yearOptions(ty);
    const k = fkey(ty, year);
    const estadoCol = (ty.cols||[]).find(c=>c.ctype==='tag' && /estado/i.test(c.label));
    const curSearch = DECL.search[k]||'', curFilter = DECL.filter[k]||'';
    const view = DECL.view[k] || 'table';

    let h = wm(0.05);
    h += '<div style="position:relative;z-index:1;">';
    h += '<div class="decl-crumb"><span onclick="declBackLanding(\''+tab.id+'\')">Declaraciones</span> › <b>'+bbEscape(ty.name)+'</b> › '+year+'</div>';

    h += '<div class="decl-typebar">';
    h += '<div class="decl-typecur" title="Volver a Declaraciones" onclick="declBackLanding(\''+tab.id+'\')"><span class="tdot" style="background:'+(ty.color||'#2f6f4f')+'"></span><i class="ti ti-file" style="font-size:15px"></i> <b>'+bbEscape(ty.name)+'</b> <i class="ti ti-chevron-left" style="font-size:12px;opacity:.6"></i></div>';
    h += '<span class="decl-sep"></span>';
    h += '<div class="decl-yearbar">';
    h += '<button class="decl-ybtn" title="Año anterior" onclick="declStepYear(\''+tab.id+'\',\''+ty.id+'\',-1)"><i class="ti ti-chevron-left"></i></button>';
    h += '<select class="decl-year-sel" onchange="declSetYear(\''+tab.id+'\',\''+ty.id+'\',this.value)">'+ yopts.map(y=>'<option value="'+y+'"'+(y===year?' selected':'')+'>'+y+'</option>').join('') +'</select>';
    h += '<button class="decl-ybtn" title="Año siguiente" onclick="declStepYear(\''+tab.id+'\',\''+ty.id+'\',1)"><i class="ti ti-chevron-right"></i></button>';
    h += '<button class="decl-ybtn add" title="Agregar un año" onclick="declAddYear(\''+tab.id+'\')"><i class="ti ti-calendar-plus"></i> Año</button>';
    h += '</div>';
    h += '<span class="decl-spacer"></span>';
    h += '<button class="decl-btn carry" onclick="declOpenCarry(\''+tab.id+'\')"><i class="ti ti-arrow-up-right"></i> Pasar clientes a otro año</button>';
    h += '</div>';

    // resumen de estados
    if(estadoCol){
      const rows=(ty.years[year].rows||[]); const counts={};
      (estadoCol.options||[]).forEach(o=>counts[o]=0); rows.forEach(r=>{ if(counts[r[estadoCol.key]]!==undefined) counts[r[estadoCol.key]]++; });
      const chips=(estadoCol.options||[]).map(o=>{ const st=tagStyle(estadoCol,o); return '<span style="display:inline-block;font-size:12px;font-weight:500;border-radius:20px;padding:3px 12px;background:'+st.bg+';color:'+st.fg+';">'+counts[o]+' '+bbEscape(o)+'</span>'; }).join(' ');
      h += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin:2px 0 12px;">'+chips+'</div>';
    }

    // toolbar
    h += '<div class="decl-toolbar">';
    h += '<div class="decl-search">🔎<input id="decl-search-input" placeholder="Buscar cliente, nota, etiqueta…" value="'+bbEscape(curSearch)+'" oninput="declOnSearch(\''+tab.id+'\',this.value)"></div>';
    if(estadoCol){ h += '<select class="decl-select" onchange="declSetFilter(\''+tab.id+'\',this.value)"><option value="">Estado: todos</option>'+(estadoCol.options||[]).map(o=>'<option value="'+bbEscape(o)+'"'+(curFilter===o?' selected':'')+'>'+bbEscape(o)+'</option>').join('')+'</select>'; }
    h += '<button class="decl-btn'+(view==='table'?' active':'')+'" onclick="declSetView(\''+tab.id+'\',\'table\')">📊 Tabla</button>';
    h += '<button class="decl-btn'+(view==='cards'?' active':'')+'" onclick="declSetView(\''+tab.id+'\',\'cards\')">🗂️ Tarjetas</button>';
    if(estadoCol) h += '<button class="decl-btn" title="Cambiar los colores de los estados" onclick="declOpenColorModal(\''+tab.id+'\',\''+ty.id+'\',\''+estadoCol.key+'\')">🎨 Colores</button>';
    h += '<button class="decl-btn" onclick="declExportCSV(\''+tab.id+'\')">⬇ Excel/CSV</button>';
    const editing = userPrefs.editMode;
    h += '<button class="decl-btn'+(editing?' active':'')+'" title="Agregar o quitar columnas" onclick="toggleEditMode()">⚙ '+(editing?'Listo':'Estructura')+'</button>';
    const _trashN=(ty.trash||[]).filter(t=>t.year===year).length;
    if(_trashN) h += '<button class="decl-btn decl-trashbtn" title="Filas que salieron al desmarcar el SI de IVA en IRPF" onclick="declOpenTrash(\''+tab.id+'\',\''+ty.id+'\')"><i class="ti ti-trash"></i> Papelera ('+_trashN+')</button>';
    h += '</div>';

    h += '<div class="decl-table-host" id="decl-table-host">'+ declRenderTable(tab, ty, year) +'</div>';
    h += '</div>';
    return h;
  }

  function declRenderTable(tab, ty, year){
    const k=fkey(ty,year); const view=DECL.view[k]||'table';
    if(view==='cards') return declRenderCards(tab, ty, year);
    const blkId=ty.years[year].id; const editing=userPrefs.editMode; const cols=ty.cols||[]; const rows=visibleRows(ty,year);
    if(!cols.length) return '<div class="decl-empty">Este tipo no tiene columnas. Activá “⚙ Estructura” y agregá una.</div>';
    let h='<table class="bb-ctable"><thead><tr>';
    if(editing) h+='<th style="width:32px;"></th>';
    cols.forEach(col=>{ const cat=(typeof COL_TYPE_CATALOG!=='undefined')?COL_TYPE_CATALOG.find(c=>c.type===col.ctype):null; const ico=cat?cat.icon:'';
      h+='<th><span>'+bbEscape(col.label)+' <span class="col-type-badge">'+ico+'</span></span>'+(editing?'<span class="col-actions"><button title="Editar columna" onclick="editCTableColumn(\''+tab.id+'\',\''+blkId+'\',\''+col.key+'\')">✎</button><button title="Eliminar columna" onclick="declRemoveCol(\''+tab.id+'\',\''+col.key+'\')">✕</button></span>':'')+'</th>'; });
    if(editing) h+='<th class="ctable-add-col" title="Agregar columna" onclick="openColConfig(\''+tab.id+'\',\''+blkId+'\',null)">+</th>';
    h+='</tr></thead><tbody>';
    if(!rows.length){ const cs=cols.length+(editing?2:0); h+='<tr><td colspan="'+cs+'" class="decl-empty">'+((DECL.search[k]||DECL.filter[k])?'Sin resultados para el filtro actual.':'Sin clientes en '+year+'. Usá “+ Cliente” abajo o “Pasar clientes a otro año”.')+'</td></tr>'; }
    else { rows.forEach(row=>{ h+='<tr data-row-key="'+row.__key+'">'; if(editing) h+='<td><button class="row-remove" title="Eliminar fila" onclick="declRemoveRow(\''+tab.id+'\',\''+row.__key+'\')">✕</button></td>'; cols.forEach(col=>{ h+='<td>'+declCell(blkId,col,row)+'</td>'; }); if(editing) h+='<td></td>'; h+='</tr>'; }); }
    const numCols=cols.filter(c=>c.ctype==='money'||c.ctype==='number');
    if(numCols.length && rows.length){ h+='<tr class="decl-foot">'; if(editing) h+='<td></td>'; cols.forEach((col,i)=>{ if(i===0){ h+='<td>Totales · '+rows.length+' cliente'+(rows.length!==1?'s':'')+'</td>'; return; } if(col.ctype==='money'||col.ctype==='number'){ const sum=rows.reduce((a,r)=>a+(Number(r[col.key])||0),0); h+='<td>'+(col.ctype==='money'?fmtMoney(sum,col.currency):sum.toLocaleString('es-UY'))+'</td>'; } else h+='<td></td>'; }); if(editing) h+='<td></td>'; h+='</tr>'; }
    h+='</tbody></table>';
    h+='<div class="bb-ctable-footer" style="margin-top:8px;"><button class="decl-btn" onclick="declAddRow(\''+tab.id+'\')">+ Cliente</button>';
    if(editing) h+=' <button class="decl-btn" onclick="openColConfig(\''+tab.id+'\',\''+blkId+'\',null)">+ Columna</button>';
    h+='</div>';
    const impCol=cols.find(c=>/importe/i.test(c.label)), timCol=cols.find(c=>/timbre/i.test(c.label));
    if(impCol&&timCol&&rows.length){ const imp=rows.reduce((a,r)=>a+(Number(r[impCol.key])||0),0), tim=rows.reduce((a,r)=>a+(Number(r[timCol.key])||0),0); h+='<div class="decl-neto">Neto ('+bbEscape(impCol.label)+' − '+bbEscape(timCol.label)+'): <b>'+fmtMoney(imp-tim,impCol.currency)+'</b></div>'; }
    return h;
  }

  function declRenderCards(tab, ty, year){ const cols=ty.cols||[]; const rows=visibleRows(ty,year); if(!rows.length) return '<div class="decl-empty">Sin resultados.</div>';
    const titleCol=cols.find(c=>c.ctype==='text')||cols[0]; let h='<div class="decl-cards">';
    rows.forEach(row=>{ h+='<div class="decl-card" style="border-left-color:'+(ty.color||'var(--c-accent)')+'"><h4>'+bbEscape(cellText(titleCol,row)||'(sin nombre)')+'</h4>';
      cols.forEach(col=>{ if(col===titleCol) return; const txt=cellText(col,row); if(!txt) return; let val=bbEscape(txt);
        if(col.ctype==='tag'){ const st=tagStyle(col,row[col.key]); const sa=st?(' style="background:'+st.bg+';color:'+st.fg+';border-color:'+st.bd+';"'):''; val='<span class="decl-chip tagged"'+sa+'>'+val+'</span>'; }
        if(col.ctype==='checkbox') val=(row[col.key]?'✅':'⬜'); h+='<div class="row"><span class="lab">'+bbEscape(col.label)+'</span><span class="val">'+val+'</span></div>'; });
      h+='</div>'; }); h+='</div>'; return h; }

  // ===== Handlers toolbar =====
  window.declOnSearch = function(tabId, val){ const tab=declTab(tabId); if(!tab) return; const ty=activeType(tab); const y=activeYear(tab,ty); DECL.search[fkey(ty,y)]=val; const host=document.getElementById('decl-table-host'); if(host) host.innerHTML=declRenderTable(tab,ty,y); };
  window.declSetFilter = function(tabId, val){ const tab=declTab(tabId); if(!tab) return; const ty=activeType(tab); const y=activeYear(tab,ty); DECL.filter[fkey(ty,y)]=val; renderContent(); };
  window.declSetView = function(tabId, v){ const tab=declTab(tabId); if(!tab) return; const ty=activeType(tab); const y=activeYear(tab,ty); DECL.view[fkey(ty,y)]=v; renderContent(); };
  window.attachDeclHandlers = function(tab){ const i=document.getElementById('decl-search-input'); if(i && i.value){ const v=i.value; i.focus(); try{ i.setSelectionRange(v.length,v.length); }catch(e){} } };

  window.declExportCSV = function(tabId){ const tab=declTab(tabId); if(!tab) return; const ty=activeType(tab); const y=activeYear(tab,ty); const cols=ty.cols||[]; const rows=visibleRows(ty,y);
    const esc=s=>'"'+String(s==null?'':s).replace(/"/g,'""')+'"'; let csv=cols.map(c=>esc(c.label)).join(',')+'\n'; rows.forEach(r=>{ csv+=cols.map(c=>esc(cellText(c,r))).join(',')+'\n'; });
    const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=(ty.name+'_'+y).replace(/[^\w\-]+/g,'_')+'.csv'; document.body.appendChild(a); a.click(); document.body.removeChild(a); if(typeof toast==='function') toast('⬇ CSV exportado'); };

  // ===== Colores de estado =====
  let _colorCtx=null;
  window.declOpenColorModal = function(tabId, typeId, colKey){ const tab=declTab(tabId); if(!tab) return; const ty=typeById(tab,typeId); if(!ty) return; const col=(ty.cols||[]).find(c=>c.key===colKey); if(!col) return; _colorCtx={tabId,typeId,colKey};
    const body=document.getElementById('decl-color-body'); body.innerHTML=(col.options||[]).map((o,i)=>{ const st=tagStyle(col,o); return '<div class="dcc-row"><input type="color" id="dcc-'+i+'" value="'+_toHex(st.bg)+'"><span class="dcc-prev" id="dccp-'+i+'" style="background:'+st.bg+';color:'+st.fg+';">'+bbEscape(o)+'</span></div>'; }).join('');
    (col.options||[]).forEach((o,i)=>{ const inp=document.getElementById('dcc-'+i); inp.addEventListener('input',function(){ const p=document.getElementById('dccp-'+i); p.style.background=inp.value; p.style.color=window.declFgFor(inp.value); }); });
    document.getElementById('decl-color-modal').classList.add('open'); };
  window.declSaveColors = function(){ if(!_colorCtx) return; const tab=declTab(_colorCtx.tabId); if(!tab) return; const ty=typeById(tab,_colorCtx.typeId); if(!ty) return; const col=(ty.cols||[]).find(c=>c.key===_colorCtx.colKey); if(!col) return;
    col.tagColors=col.tagColors||{}; (col.options||[]).forEach((o,i)=>{ const inp=document.getElementById('dcc-'+i); if(inp) col.tagColors[o]=inp.value; }); saveState(); closeModal('decl-color-modal'); renderContent(); if(typeof toast==='function') toast('🎨 Colores guardados'); };
  function _toHex(c){ if(!c) return '#cccccc'; if(c[0]==='#'&&c.length===7) return c; const m=c.match(/(\d+)/g); if(m&&m.length>=3) return '#'+m.slice(0,3).map(x=>('0'+parseInt(x).toString(16)).slice(-2)).join(''); return '#cccccc'; }

  // ===== Traspaso de clientes =====
  let _carryCtx=null;
  window.declOpenCarry = function(tabId){ const tab=declTab(tabId); if(!tab) return; const ty=activeType(tab); const y=activeYear(tab,ty); const rows=(ty.years[y].rows||[]); if(!rows.length){ toast('No hay clientes en '+y+' para pasar'); return; }
    _carryCtx={tabId,typeId:ty.id,fromYear:y}; const idCol=(ty.cols||[]).find(c=>c.ctype==='text')||ty.cols[0];
    document.getElementById('decl-carry-sub').textContent='Tipo “'+ty.name+'” · desde el año '+y;
    document.getElementById('decl-carry-dest').value=String(parseInt(y)+1);
    document.getElementById('decl-carry-clients').innerHTML=rows.map(r=>{ const nm=bbEscape(cellText(idCol,r)||'(sin nombre)'); return '<label class="dca-row"><input type="checkbox" class="dca-cli" data-key="'+r.__key+'" checked> '+nm+'</label>'; }).join('');
    document.getElementById('decl-carry-cols').innerHTML=(ty.cols||[]).map(c=>{ const isId=c.key===idCol.key; const pre=isId||/medio|ejecutor/i.test(c.label); return '<label class="dca-row"><input type="checkbox" class="dca-col" data-key="'+c.key+'" '+(pre?'checked':'')+(isId?' disabled':'')+'> '+bbEscape(c.label)+(isId?' <span class="dca-fix">(siempre)</span>':'')+'</label>'; }).join('');
    document.getElementById('decl-carry-modal').classList.add('open'); };
  window.declCarryAll = function(on){ document.querySelectorAll('#decl-carry-clients .dca-cli').forEach(c=>{ c.checked=on; }); };
  window.declDoCarry = function(){ if(!_carryCtx) return; const tab=declTab(_carryCtx.tabId); if(!tab) return; const ty=typeById(tab,_carryCtx.typeId); if(!ty) return; const fromY=_carryCtx.fromYear;
    const destY=String(document.getElementById('decl-carry-dest').value).trim(); if(!/^\d{4}$/.test(destY)){ toast('Poné un año destino válido'); return; }
    const idCol=(ty.cols||[]).find(c=>c.ctype==='text')||ty.cols[0];
    const cliKeys=[...document.querySelectorAll('#decl-carry-clients .dca-cli:checked')].map(c=>c.dataset.key);
    let colKeys=[...document.querySelectorAll('#decl-carry-cols .dca-col:checked')].map(c=>c.dataset.key); if(!colKeys.includes(idCol.key)) colKeys.unshift(idCol.key);
    if(!cliKeys.length){ toast('Elegí al menos un cliente'); return; }
    if(!ty.years[destY]) ty.years[destY]={id:_id('dyr'),rows:[]}; const dest=ty.years[destY];
    const existing=new Set((dest.rows||[]).map(r=>String(r[idCol.key]||'').trim().toLowerCase()).filter(Boolean));
    const src=(ty.years[fromY].rows||[]); let added=0, skipped=0;
    cliKeys.forEach(key=>{ const r=src.find(x=>x.__key===key); if(!r) return; const nm=String(r[idCol.key]||'').trim().toLowerCase(); if(nm && existing.has(nm)){ skipped++; return; } const nr={__key:_rk()}; colKeys.forEach(ck=>{ if(r[ck]!==undefined) nr[ck]=r[ck]; }); dest.rows.push(nr); if(nm) existing.add(nm); added++; });
    DECL.nav[tab.id]=ty.id; userPrefs['declYear_'+tab.id+'_'+ty.id]=destY; userPrefs['declType_'+tab.id]=ty.id; saveUserPrefs(); saveState(); closeModal('decl-carry-modal'); renderContent();
    toast('⤴ '+added+' cliente'+(added!==1?'s':'')+' pasado'+(added!==1?'s':'')+' a '+destY+(skipped?' · '+skipped+' ya existían':'')); };

  // ===== Modales =====
  function injectModals(){
    if(!document.getElementById('decl-color-modal')){ const w=document.createElement('div'); w.id='decl-color-modal'; w.className='modal-overlay';
      w.innerHTML='<div class="modal" style="width:340px;max-width:92vw;position:relative;"><button class="modal-close" onclick="closeModal(\'decl-color-modal\')">×</button><h3>🎨 Colores de estado</h3><div class="modal-sub">Asigná un color a cada estado. Se aplica en la tabla y en las tarjetas.</div><div id="decl-color-body" style="margin:8px 0 4px;"></div><div style="display:flex;gap:8px;margin-top:16px;justify-content:flex-end;"><button class="decl-btn" onclick="closeModal(\'decl-color-modal\')">Cancelar</button><button class="decl-btn primary" onclick="declSaveColors()">Guardar</button></div></div>'; document.body.appendChild(w); }
    if(!document.getElementById('decl-trash-modal')){ const w=document.createElement('div'); w.id='decl-trash-modal'; w.className='modal-overlay';
      w.innerHTML='<div class="modal" style="width:440px;max-width:92vw;position:relative;"><button class="modal-close" onclick="closeModal(\'decl-trash-modal\')">×</button><h3>🗑 Papelera</h3><div class="modal-sub">Filas que salieron de IVA al desmarcar el “SI” en IRPF. Podés restaurarlas (con su fecha y nota) o eliminarlas para siempre.</div><div id="decl-trash-body" style="margin:8px 0 4px;max-height:320px;overflow:auto;"></div><div style="display:flex;gap:8px;margin-top:14px;justify-content:flex-end;"><button class="decl-btn" onclick="closeModal(\'decl-trash-modal\')">Cerrar</button></div></div>'; document.body.appendChild(w); }
    if(!document.getElementById('decl-carry-modal')){ const w=document.createElement('div'); w.id='decl-carry-modal'; w.className='modal-overlay';
      w.innerHTML='<div class="modal" style="width:560px;max-width:94vw;position:relative;"><button class="modal-close" onclick="closeModal(\'decl-carry-modal\')">×</button><h3>⤴ Pasar clientes a otro año</h3><div class="modal-sub" id="decl-carry-sub"></div><div class="dca-dest"><label>Año destino</label> <input type="number" id="decl-carry-dest" class="dca-destinp"></div><div class="dca-cols2"><div class="dca-box"><div class="dca-h">Clientes a pasar <button class="dca-mini" onclick="declCarryAll(true)">Todos</button><button class="dca-mini" onclick="declCarryAll(false)">Ninguno</button></div><div id="decl-carry-clients" class="dca-list"></div></div><div class="dca-box"><div class="dca-h">Datos a copiar</div><div id="decl-carry-cols" class="dca-list"></div></div></div><div class="modal-sub" style="margin-top:6px;">Lo que no marques arranca en blanco en el año destino. Los clientes que ya existan en ese año no se duplican.</div><div style="display:flex;gap:8px;margin-top:14px;justify-content:flex-end;"><button class="decl-btn" onclick="closeModal(\'decl-carry-modal\')">Cancelar</button><button class="decl-btn primary" onclick="declDoCarry()">Pasar clientes</button></div></div>'; document.body.appendChild(w); }
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', injectModals); else injectModals();
})();
